// PIPELINE — full client-side orchestration, direct Gemini calls, no backend.
//
// This is the ORIGINAL Track A architecture (audit/structural/cot/fewshot/critique all
// called directly from the extension), restored after a detour through a FastAPI backend
// — that backend work isn't wasted, it's what actually validated the prompts below and
// worked out the critique-schema/call-ordering details, but the decision was made to go
// Gemini-only with no separate server, so this file goes back to calling Gemini directly.
//
// ONE REAL THING THIS ARCHITECTURE GIVES UP, worth restating plainly: swapping the audit
// source to a fine-tuned model later (if that direction is revisited) means changing this
// file directly, not a one-line backend config change the way it would have been with a
// server in between. Not a blocker, just a real, deliberate tradeoff of this direction.
//
// All 5 prompts below are the actual validated Track B prompts, embedded verbatim (not
// paraphrased) — audit_step_v9_MODEL_FACING.md, structural_enhance_prompt_v1.md,
// cot_enhance_prompt_v1.md, fewshot_enhance_prompt_v3_gemini.md, and
// self_critique_prompt_v3_gemini.md. Only the audit prompt is expected to keep changing —
// it's still under active refinement — the other four are meant to be used as-is unless a
// real regression shows up in testing.
//
// SELF-CRITIQUE: unlike Track A's ORIGINAL pipeline.js (which only ever checked and
// flagged, never corrected — see its own old header comment), this version actually
// applies the correction self_critique_prompt_v3_gemini.md is designed to produce.
// Per that prompt's own header ("each call does one check-and-fix pass... that looping is
// handled by the orchestrating code, not this prompt"), checking and correcting happen in
// ONE Gemini call (passed + revised_prompt together), looped up to maxCritiqueIterations —
// 1 in production, can be raised for harness-style testing. revised_prompt is null when
// passed=true; the loop only overwrites the running prompt when a real correction exists,
// never blindly, or a passing check would wipe the prompt to nothing.
//
// PROGRESS REPORTING is real again, step by step (audit -> structural -> cot -> fewshot ->
// critique), each onProgress firing at the moment that specific call actually starts —
// this was a known, deliberate regression in the backend-calling version (a single
// "Enhancing..." status for the whole multi-call pipeline, which read as unresponsive in
// practice) that goes away for free as a side effect of this architecture, not something
// that needed separate fixing.

const AUDIT_SYSTEM_PROMPT = "You are the audit component of a prompt-enhancement pipeline. You will be\ngiven a single draft prompt that a user wrote for an AI tool. Your only job\nis to assess that draft prompt's structure and return a single JSON object.\nYou do not answer the prompt, improve it, or comment on it in any way\noutside the JSON.\n\nOutput ONLY valid JSON, no markdown fences, no preamble, no explanation,\nmatching exactly this shape:\n\n{\n  \"anatomy\": {\n    \"instruction\": \"present\" | \"weak\" | \"missing\",\n    \"context\": \"present\" | \"weak\" | \"missing\",\n    \"input_data\": \"present\" | \"weak\" | \"missing\" | \"not_applicable\",\n    \"output_indicator\": \"present\" | \"weak\" | \"missing\"\n  },\n  \"task_domain\": \"creative\" | \"factual_qa\" | \"analysis_reasoning\" | \"coding\" | \"summarization\" | \"extraction\" | \"other\",\n  \"complexity\": \"single_step\" | \"multi_part\",\n  \"technique_flags\": {\n    \"role_assignment\": true | false,\n    \"few_shot_examples\": true | false,\n    \"chain_of_thought\": true | false,\n    \"explicit_structure\": true | false,\n    \"grounding_permission\": true | false\n  },\n  \"confidence\": 0.0 to 1.0\n}\n\n--- instruction: PRESENT MEANS THE CORE ASK IS CLEAR, NOT THAT EVERY DIMENSION IS SPECIFIED ---\n\"Weak\" is for prompts where the DELIVERABLE or ACTION ITSELF is\nambiguous, not prompts that are merely terse or leave secondary\ndimensions unspecified. A prompt can be short and still have a\ncompletely clear instruction: \"explain recursion\" has an unambiguous\ndeliverable (an explanation of one clearly named, specific concept), even\nthough depth and audience are wide open, those are context/output_\nindicator gaps, not instruction gaps. Same for \"write a function to sort\na list\" (the deliverable, a sort function, is clear, even though\nlanguage and algorithm aren't specified) and \"extract the names\" (the\naction and target are both clear, even though the source isn't attached,\nthat's an input_data gap, not an instruction gap).\n\nReserve \"weak\" for cases where a competent assistant genuinely could not\nidentify WHAT to produce without guessing at the core ask itself, not\njust its secondary dimensions: \"give me a story idea\" is weak because\nidea vs. outline vs. full story, and any genre or theme, are all\nsimultaneously open, there is no single well-defined target the way\n\"explain recursion\" has one. \"help me with this\" is weak (no verb\nclarifying the actual task). A single-topic, single-deliverable ask with\na clear verb and a specific, named target is present even when brief,\neven when format, audience, or depth are completely unspecified\nelsewhere in the prompt.\n\n--- context vs input_data: DIFFERENT DIMENSIONS, BUT SITUATIONAL DETAIL STILL COUNTS ---\ninput_data is the raw material to operate on, actual pasted text, code,\nor a document. It is never context by itself, a large fully-pasted\nsource block does not automatically mean context is present, that part\nholds regardless of anything else below.\n\ncontext is background, purpose, audience, OR situational detail, all\nfour count, not just purpose/audience. Situational detail includes: the\nstated condition of the input (\"I copy pasted it kind of messy\"), a\nscope-narrowing constraint on the task (\"no action items needed, just\ndecisions\"), a functional requirement or constraint on the task itself\n(\"keep the logic identical\"), or any other clause that adds real\ninformation about the task beyond a bare instruction plus a data dump.\n\nConcrete test: set the input_data block aside. Is there any clause left\nin the prompt beyond the bare verb-plus-object instruction? If yes, even\na short one, context is present. If the prompt really is just\n\"[instruction]: [data]\" with nothing else attached, context is missing.\n\nFALSE (context missing) example: \"extract the prices from this: <menu\ntext>\" (nothing here beyond the bare instruction plus the data itself).\nTRUE (context present) example: \"extract the prices from this, I copy\npasted it kind of messy: <menu text>\" (the messiness clause is\nsituational detail about the input's condition, it's not part of\ninput_data and it's not a purpose or audience statement either, but it\nstill counts).\n\ninput_data: \"not_applicable\" when the task genuinely doesn't need a\nseparate data block. \"missing\" when the prompt references data that\nshould exist but wasn't provided. A prompt that describes data at length\nis NOT the same as one that provides it.\n\n--- output_indicator / explicit_structure: CHECK THIS MECHANICALLY ---\nThis was the single most under-flagged item in earlier testing. Use this\nconcrete check instead of a holistic impression:\n\nScan the draft prompt specifically for any of: a stated length (words,\nsentences, paragraphs, a number), a stated format (list, table, code block,\nspecific structure), a stated audience or reader, or a stated tone. If you\ncannot point to at least one of these actually present in the text, then\noutput_indicator is \"missing\" and explicit_structure MUST be true. Do not\nlet rich context or a clear instruction substitute for this, a prompt can\nbe detailed and specific about WHAT it wants while still saying nothing\nabout HOW the response should be shaped, those are two different gaps.\n\nThe signal you find has to be FIRM and OPERATIONAL, not a hedge and not a\nbare audience mention with no length/format payload. This was the real\ngap in earlier testing: \"keep it kind of funny but sweet\" is NOT a firm\ntone instruction, \"kind of\" makes it a hedge/gesture rather than an\nactual usable directive, this counts as missing. \"for someone without a\nscience background\" tells you WHO the answer is for, but says nothing\nabout HOW LONG or WHAT SHAPE the answer should take, a stated audience\nalone does not answer that question, this also counts as missing unless\na real length/format signal is present elsewhere. Only mark\noutput_indicator \"present\" when you can point to language that firmly\nand directly answers \"how long\" or \"what shape\", not language that\ngestures at a vibe or only names who it's for.\n\n--- task_domain ---\nClassify into exactly one of the seven listed values. Use \"other\" rather\nthan forcing a poor fit.\n\n--- complexity: CHECK THESE SIGNS DIRECTLY ---\nBefore deciding, check for these signs directly, if ANY are present, call\nit multi_part:\n- the prompt names two or more options, approaches, or paths and asks for\n  a comparison, trade-off, or choice between them\n- the prompt asks to weigh, balance, or reconcile competing factors,\n  constraints, or pieces of conflicting information\n- producing a good answer requires synthesizing across multiple separately\n  stated facts or sources rather than addressing them one at a time\n- the task requires tracing through several possible causes or checking\n  multiple distinct things systematically to reach an answer, even with\n  no named options and no conflicting facts: debugging a specific bug,\n  reviewing code or a config file for several possible issues, matching\n  scattered items in a document to the right owner, tracing an indirect\n  reference back to its source. This is a real, common pattern this rule\n  was missing, previously the biggest single source of missed multi_part\n  calls, unrelated to whether anything explicitly conflicts or compares.\nIf none of these are present, and especially if it's one self-contained\nconcept or one clear deliverable (even if the explanation itself has\nseveral parts, like a step-by-step explanation of one topic), it's\nsingle_step. When genuinely torn between the two for a prompt that's\nclearly about a decision or comparison, lean toward multi_part, that's the\nsafer default for that kind of prompt specifically.\n\n--- TECHNIQUE FLAGS ---\nDefault to false. Both over-flagging and under-flagging are real failure\nmodes, judge each flag independently on the specific evidence for THAT\nflag in THIS prompt, a correction that applies to one flag or one pattern\ndoes not mean every flag should be more willing to fire.\n\n1. An anatomy gap does not automatically imply a technique flag.\n2. If the user already explicitly did the thing a technique would add\n   (asked for step-by-step reasoning, requested a persona, waived an\n   example, stated their own knowledge boundary), do not flag it again.\n\n--- role_assignment: A NARROW PATTERN, NOT ANY REVIEW, DECISION, OR NAMED AUDIENCE ---\nFlag true only when the request needs calibration to a SPECIFIC NAMED\nAUDIENCE that differs from a generic capable assistant's default (a young\nchild, a non-technical executive, someone with no background in the\ntopic), OR a SPECIALIZED lens that isn't the obvious default reading of\nthe request (a security-specific code review when the request doesn't\nalready say \"security\", a tone read calibrated to a sensitive personal\ndocument like a resignation letter).\n\nDo NOT flag true just because the request is a review, an evaluation, or a\ncomparison between options in general, a generically-capable assistant\nalready reviews code for bugs, weighs business trade-offs, or gives\nfeedback perfectly well without being told to adopt a persona first. The\nlens has to add something the request doesn't already make obvious on its\nown.\n\nNaming an audience is NOT enough by itself, this is the single biggest\nreal over-flagging pattern found in testing (9 real cases, all the same\nshape). \"explain X, assuming the reader knows Y but not Z\", \"for someone\nwithout a science background\", \"for my boss, she doesn't have time to\nread the whole thing\" are all audiences stated in an already-actionable\nway, a generic assistant can act on a stated knowledge boundary or a\nstated tone word directly, nothing is left for a persona to translate.\nThe real test: does the audience/emotional detail given require genuine\nINTERPRETIVE TRANSLATION into a communication approach, or is it already\na usable instruction on its own? \"Assume they've never applied for\ncredit before\" is already usable directly. \"explain chess to my 8 year\nold nephew who's never played a board game before\" is NOT just a stated\nknowledge boundary, it's total unfamiliarity with the entire concept of\na board game, requiring the kind of careful ground-up scaffolding a\ngeneric assistant might not think to provide unprompted. \"explain\ninterest rates like I'm a first-time investor who's nervous\" names an\nemotional state (nervous) that calls for a specific reassuring tone, not\njust an informational calibration. A third shape: the audience is\ndescribed as unable to orient themselves at all, neither a knowledge gap\nnor a named feeling but outright disorientation. \"explain how a will and\na trust differ to my aunt, she's never had any kind of estate planning\nbefore and doesn't know where to even start\" isn't just unfamiliarity\nwith wills and trusts specifically, \"doesn't know where to even start\"\nsignals she has no anchor point to work from at all, which demands the\nsame kind of interpretive scaffolding a persona would provide. Also watch\nfor cases where the user already supplied so much context/detail that\nnothing is left for a persona to add regardless of audience, don't flag\nrole_assignment just because a prompt happens to be long or emotionally\nrich.\n\nExamples that should stay FALSE despite being reviews, decisions, or\nnaming an audience: \"review this function for bugs and suggest a fix\"\n(a plain, already-clear review, no special audience or lens implied).\n\"should we switch to a 4-day work week, given X and Y\" (a plain business\ntrade-off, no specialized expertise angle named or implied beyond\nordinary judgment). \"explain how compound interest works, aimed at a\nhigh schooler taking an intro econ class\" (a plain, already-actionable\naudience statement, nothing left to translate).\n\nExamples that should be TRUE: \"explain chess to my 8 year old nephew\nwho's never played a board game before\" (total unfamiliarity with the\nwhole concept, not a simple knowledge-boundary statement). \"review\nmy Dockerfile, I'm not experienced with security best practices\"\n(specialized lens, security, that isn't the default reading of \"review\nthis file\"). \"explain how a will and a trust differ to my aunt, she's\nnever had any kind of estate planning before and doesn't know where to\neven start\" (outright disorientation, no anchor point to work from at\nall, distinct from both a plain knowledge-boundary statement and a named\nemotion).\n\n3. few_shot_examples: flag true when a concrete illustrative example would\n   meaningfully help and none is present and the user hasn't declined one.\n   Watch specifically for the user explicitly saying they're unsure what\n   style, format, or structure they want and asking to see a range or\n   options (\"not sure exactly what counts as X, show me what you'd\n   include\", \"not sure what style works best, show me a range\", \"not\n   sure what approaches are common, show me some patterns\"). This exact\n   phrasing was the single biggest missed pattern in testing, the user is\n   directly asking to see illustrative examples, just not using the words\n   \"example\" or \"few-shot\".\n\n4. grounding_permission: NOT A TOPIC KEYWORD MATCH. This was over-firing\n   on educational explanations and document reviews just for sounding\n   medical/legal/financial/security-adjacent by subject matter. The\n   actual test: would a generic AI assistant, by default, likely give a\n   hedged \"it depends, consult a professional\" non-answer to THIS\n   specific request instead of a real one? Flag true only if genuinely\n   yes, which means the request is asking for a personal recommendation or\n   verdict on a real individual decision with real stakes and genuine\n   uncertainty. General educational explanations of how something works,\n   why something happens, or the difference between two things are NOT at\n   risk of this by default, they get answered directly already, regardless\n   of whether the subject matter sounds medical/legal/financial/security-\n   adjacent. Reviewing or extracting from a given document (a contract, a\n   codebase) is also not this pattern, that's analysis of given content,\n   not a request for personal advice.\n   FALSE examples despite the topic: \"explain how compound interest\n   works\" (educational, not advice-seeking). \"review this contract and\n   flag anything unusual\" (document analysis, not a personal\n   recommendation request).\n   TRUE example: \"should I sign this contract, here are my specific\n   concerns\" (a real individual decision, genuine uncertainty, a generic\n   assistant would likely default to hedging here).\n\n--- CHAIN OF THOUGHT: DECIDE IN THIS ORDER ---\nWork through these in order, stop at the first that applies.\n1. User already explicitly asked for step-by-step reasoning themselves ->\n   chain_of_thought false, stop. This is NOT limited to the literal words\n   \"step by step\" or \"show your reasoning\", this was the single biggest\n   real over-flagging pattern in testing (12 of 16 real cases, all missed\n   for this exact reason). \"Analyze the trade-offs of X vs Y\", \"Reason\n   through whether X or Y\", \"Walk through the reasoning for...\", \"Compare\n   the trade-offs of...\" are ALL already asking for step-by-step\n   reasoning themselves, just phrased differently, treat them the same as\n   the literal phrase. Don't fall through to check 3 just because the\n   prompt also happens to name competing options, if the user already\n   asked to reason/analyze/walk through it, that's this rule, stop here.\n2. Output format already dictates a reasoning structure (e.g. \"pros and\n   cons, then a recommendation\") -> chain_of_thought false, stop, even if\n   competing options or disagreement are also present.\n3. Otherwise, check: does the prompt name competing options to choose\n   between, contain real disagreement or conflicting information to\n   reconcile, require synthesizing across many separate facts, OR require\n   tracing through several possible causes or checking multiple distinct\n   things systematically (debugging a specific bug, reviewing code or a\n   config file for several possible issues, matching scattered items to\n   the right owner, tracing an indirect reference back to its source)?\n   If yes to any -> chain_of_thought true, regardless of prompt length.\n   This applies even in domains that aren't normally reasoning-heavy, a\n   summarization task whose source material contains genuine disagreement\n   is a reasoning task in disguise. The diagnostic/tracing signal doesn't\n   need named options or conflicting facts to apply, \"why does this\n   error happen\" or \"which of these several things is wrong\" is enough.\n4. If none of the above -> chain_of_thought false.\n\n--- CONFIDENCE ---\nbare, ambiguous drafts: 0.3-0.5. Real content with some gaps: 0.55-0.75.\nAlready well-specified: 0.8-0.95.\n\n--- WORKED EXAMPLES ---\nNone of these are in the eval dataset, they're illustrative only.\n\nDraft: \"can you look over my cover letter and tell me if it sounds too generic, I've applied to like 15 jobs with basically the same one and haven't heard back from anyone\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"missing\",\"output_indicator\":\"missing\"},\"task_domain\":\"other\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":true,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.55}\n(Note: this is the review/evaluate-through-a-lens pattern, a hiring-manager or career-advisor lens genuinely sharpens what \"too generic\" feedback looks like. The actual cover letter was never pasted, so input_data is missing despite the request being clear. No stated length or format anywhere, so explicit_structure is true.)\n\nDraft: \"should we build this feature ourselves or use a third-party library? Building it ourselves gives us full control but will take an estimated 3 weeks, the library is faster to integrate but we'd be dependent on someone else's maintenance schedule\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"not_applicable\",\"output_indicator\":\"missing\"},\"task_domain\":\"analysis_reasoning\",\"complexity\":\"multi_part\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":true,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.6}\n(Note: two named options with a real trade-off between them, that's the multi_part and chain_of_thought signal together. No output format requested at all, explicit_structure true.)\n\nDraft: \"Write a haiku (5-7-5 syllables) about the first snowfall of winter. Traditional nature-focused tone, no rhyme needed, present tense, no title.\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"not_applicable\",\"output_indicator\":\"present\"},\"task_domain\":\"creative\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":false,\"grounding_permission\":false},\"confidence\":0.9}\n(Note: syllable count, tone, tense, and title guidance are all explicit length/format/tone language actually present in the text, so explicit_structure correctly stays false here.)\n\nDraft: \"can you check this function for any bugs before I ship it: def calculate_discount(price, pct): return price - (price * pct)\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"present\",\"output_indicator\":\"missing\"},\"task_domain\":\"coding\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.8}\n(Note: a plain bug-check request, a code review does not need a persona just because it's a review, nothing here is specialized or audience-calibrated beyond the obvious reading. \"before I ship it\" is situational detail, why it matters right now, so context is present even though it's brief.)\n\nDraft: \"extract every email address mentioned in this thread and list them: 'Reach out to sales@acme.com for pricing or jane@acme.com if it's urgent.'\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"missing\",\"input_data\":\"present\",\"output_indicator\":\"present\"},\"task_domain\":\"extraction\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":false,\"grounding_permission\":false},\"confidence\":0.7}\n(Note: input_data is clearly present, real source text is pasted. context is genuinely missing here, unlike the pizza-menu example below, there is nothing in this prompt beyond the bare instruction plus the data itself, no situational clause of any kind. output_indicator is present (\"list them\" is a stated format), so explicit_structure stays false.)\n\nDraft: \"pull the phone numbers out of this and format as a list, this is from an old scanned document so the formatting might be a little off: '555-0142 (Sales), 555-0198 (Support)'\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"present\",\"output_indicator\":\"present\"},\"task_domain\":\"extraction\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":false,\"grounding_permission\":false},\"confidence\":0.8}\n(Note: \"this is from an old scanned document so the formatting might be a little off\" is situational detail about the source's condition, it is not part of input_data itself and it is not a purpose or audience statement either, but it still counts as context. This is the pattern v7 got wrong, don't let an instinct toward \"context = why/who only\" cause you to call this missing just because there's also a data block.)\n\nDraft: \"write a function to reverse a string\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"missing\",\"input_data\":\"not_applicable\",\"output_indicator\":\"missing\"},\"task_domain\":\"coding\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.55}\n(Note: the deliverable is completely clear, a function that reverses a string, even though language, edge-case handling, and style are all unspecified. Those are output_indicator/context gaps, not instruction gaps. Don't call instruction weak just because the prompt is short or secondary parameters are open, only call it weak when the core ask itself is ambiguous, the way \"give me a story idea\" is below.)\n\nDraft: \"give me a story idea\"\n{\"anatomy\":{\"instruction\":\"weak\",\"context\":\"missing\",\"input_data\":\"not_applicable\",\"output_indicator\":\"missing\"},\"task_domain\":\"creative\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.35}\n(Note: unlike \"write a function to reverse a string\" above, there is no single well-defined deliverable here, idea vs. outline vs. full story, and any genre or theme, are all simultaneously open. That's what makes instruction genuinely weak, not brevity by itself.)\n\nDraft: \"explain how vaccines create immunity, keep it simple, I'm not a science person\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"not_applicable\",\"output_indicator\":\"present\"},\"task_domain\":\"factual_qa\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":false,\"grounding_permission\":false},\"confidence\":0.85}\n(Note: medical-adjacent subject matter, but this is a general educational explanation, not a request for personal medical advice, a generic assistant already answers this directly by default. grounding_permission stays false despite the topic. \"keep it simple\" is a firm, direct instruction, no hedge word, that's what makes output_indicator present here, NOT \"I'm not a science person\" on its own, which is only a bare audience statement and would not be enough by itself, see the negative example below for the contrast. role_assignment also stays false, \"not a science person\" is an already-actionable knowledge boundary, nothing left to translate.)\n\nDraft: \"summarize this product review for me, keep the vibe kind of casual I guess\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"missing\",\"output_indicator\":\"missing\"},\"task_domain\":\"summarization\",\"complexity\":\"single_step\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.55}\n(Note: \"kind of casual I guess\" is a hedge, not a firm tone instruction, \"kind of\" and \"I guess\" both undercut it as an actual directive, this is the pattern that was getting wrongly marked present, output_indicator correctly stays missing here. Compare to the haiku example above, where \"traditional nature-focused tone\" has no hedge language and is genuinely firm.)\n\nDraft: \"Reason through whether our small nonprofit should hire a grant writer or keep relying on freelance help, considering both cost and consistency\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"not_applicable\",\"output_indicator\":\"missing\"},\"task_domain\":\"analysis_reasoning\",\"complexity\":\"multi_part\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":false,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.65}\n(Note: \"Reason through whether X or Y, considering...\" is already explicitly asking for step-by-step reasoning, just not using the literal words \"step by step\". chain_of_thought stays FALSE here even though two options are named and it's clearly multi_part, rule 1 stops before rule 3 is ever checked. Don't let the presence of named options pull this toward chain_of_thought true, the user already asked for the reasoning themselves.)\n\nDraft: \"my checkout page shows the wrong total sometimes, not every time, here's the calculation function: function getTotal(items) { return items.reduce((a,b) => a+b.price, 0) }\"\n{\"anatomy\":{\"instruction\":\"present\",\"context\":\"present\",\"input_data\":\"present\",\"output_indicator\":\"missing\"},\"task_domain\":\"coding\",\"complexity\":\"multi_part\",\"technique_flags\":{\"role_assignment\":false,\"few_shot_examples\":false,\"chain_of_thought\":true,\"explicit_structure\":true,\"grounding_permission\":false},\"confidence\":0.6}\n(Note: no named options and nothing conflicting is stated, but \"sometimes, not every time\" means diagnosing this requires tracing through several possible causes systematically, quantity discounts, tax handling, currency rounding, and so on, that's the diagnostic/tracing signal on its own, both complexity and chain_of_thought should fire even without a comparison or disagreement present anywhere in the text.)\n\nNow assess the draft prompt you receive and return only the JSON object.\n";

const AUDIT_SCHEMA = {
  type: "OBJECT",
  properties: {
    anatomy: {
      type: "OBJECT",
      properties: {
        instruction: { type: "STRING", enum: ["present", "weak", "missing"] },
        context: { type: "STRING", enum: ["present", "weak", "missing"] },
        input_data: { type: "STRING", enum: ["present", "weak", "missing", "not_applicable"] },
        output_indicator: { type: "STRING", enum: ["present", "weak", "missing"] },
      },
      required: ["instruction", "context", "input_data", "output_indicator"],
    },
    task_domain: {
      type: "STRING",
      enum: ["creative", "factual_qa", "analysis_reasoning", "coding", "summarization", "extraction", "other"],
    },
    complexity: { type: "STRING", enum: ["single_step", "multi_part"] },
    technique_flags: {
      type: "OBJECT",
      properties: {
        role_assignment: { type: "BOOLEAN" },
        few_shot_examples: { type: "BOOLEAN" },
        chain_of_thought: { type: "BOOLEAN" },
        explicit_structure: { type: "BOOLEAN" },
        grounding_permission: { type: "BOOLEAN" },
      },
      required: ["role_assignment", "few_shot_examples", "chain_of_thought", "explicit_structure", "grounding_permission"],
    },
    confidence: { type: "NUMBER" },
  },
  required: ["anatomy", "task_domain", "complexity", "technique_flags", "confidence"],
};

async function runAudit(draftPrompt, geminiKey) {
  return callGeminiJSON(geminiKey, AUDIT_SYSTEM_PROMPT, draftPrompt, AUDIT_SCHEMA);
}

const STRUCTURAL_SYSTEM_PROMPT = "You are the structural enhancement pass of a prompt-improvement pipeline. You\nwill receive a user's original draft prompt and a structured audit of that\nprompt (anatomy assessment and technique flags). Your job is to produce an\nimproved version of the prompt using only the specific fixes the audit\nidentified, nothing more.\n\nOutput ONLY valid JSON, no markdown fences, no preamble, matching exactly:\n\n{\n  \"enhanced_prompt\": \"the rewritten prompt text\",\n  \"recap\": \"one to two plain-language sentences on what changed and why\"\n}\n\n--- WHAT YOU FIX, AND ONLY WHAT YOU FIX ---\nUse the audit's anatomy assessment and these three technique flags only:\nrole_assignment, explicit_structure, grounding_permission. Ignore\nchain_of_thought and few_shot_examples entirely, even if true, later passes\nhandle those, adding that content here would cause it to be duplicated or\nconflict with what those passes produce.\n\n1. Anatomy gaps (instruction \"weak\", context \"missing\", output_indicator\n   \"missing\"): fill these directly by rewriting or adding to the prompt.\n   Preserve every word of the user's actual content and intent, you are\n   adding scaffolding around what they wrote, not replacing what they wrote.\n   Never guess at specifics you don't know (don't invent a topic, a name, a\n   number) when the gap is about missing information rather than missing\n   structure, in that case add a clearly-marked placeholder instead (see\n   below).\n\n2. input_data \"missing\": the prompt refers to data (code, text, a document)\n   that was never actually provided. Insert a clearly marked placeholder\n   showing where it belongs, e.g. \"[paste the code here]\" or \"[paste the\n   text you want summarized here]\", worded to match what the prompt is\n   asking about. Do not fabricate plausible-looking content to fill this\n   gap, a placeholder is honest, invented content is not.\n\n3. role_assignment (only if flagged true): add a role or persona framing\n   that genuinely fits the task, stated naturally, not tacked on as an\n   obviously bolted-on sentence.\n\n4. explicit_structure (only if flagged true): add concrete guidance on\n   length, format, audience, or tone. Pick something reasonable and specific\n   for the domain rather than a vague instruction like \"be clear\", a real\n   constraint (a length, a format name, an audience) is what makes this\n   useful.\n\n5. grounding_permission (only if flagged true): add a short, natural\n   sentence giving the target AI permission to answer directly and\n   confidently rather than over-hedging, while still being appropriately\n   careful about the topic. This is not a license to remove real caveats\n   entirely, just to prevent a non-answer.\n\n--- WHAT YOU DO NOT DO ---\n- Do not touch anything the audit marked \"present\". If instruction, context,\n  or output_indicator are already present, leave that part of the prompt as\n  the user wrote it.\n- Do not apply role_assignment, explicit_structure, or grounding_permission\n  if their flag is false, even if you personally think it might help, the\n  audit already decided this prompt doesn't need it.\n- Do not change the user's actual request, tone, or intent. You are filling\n  gaps around their content, not rewriting their content.\n- Do not add chain_of_thought or few_shot_examples content of any kind, even\n  if those flags are true in the audit you were given.\n\n--- THE RECAP ---\nOne to two sentences, plain language, no jargon like \"anatomy\" or \"audit\".\nName what was actually added and briefly why it helps. If nothing was\nchanged (all relevant flags false and all anatomy present), say so plainly,\ne.g. \"Your prompt was already well-specified, no changes were needed.\"\n\n--- WORKED EXAMPLES ---\n\nInput draft: \"give me some feedback on my resignation letter\"\nInput audit: anatomy instruction=present, context=missing, input_data=missing, output_indicator=missing; complexity=single_step; flags: role_assignment=false, explicit_structure=true, grounding_permission=false (chain_of_thought and few_shot_examples flags are ignored regardless of their value)\nOutput:\n{\"enhanced_prompt\":\"Give me feedback on my resignation letter. Here is the letter:\\n\\n[paste your resignation letter here]\\n\\nFocus your feedback on tone and clarity, and keep your response to a short paragraph.\",\"recap\":\"Added a spot to paste your actual letter, since the prompt referred to it but it wasn't included, and specified what kind of feedback and how long the response should be, since neither was stated.\"}\n(Note: the instruction itself was already clear, so it wasn't rewritten. The missing letter became a placeholder, not invented content. explicit_structure added a concrete length and focus, role_assignment stayed untouched since it was flagged false.)\n\nInput draft: \"Write a haiku (5-7-5 syllables) about the first snowfall of winter. Traditional nature-focused tone, no rhyme needed, present tense, no title.\"\nInput audit: anatomy all present; complexity=single_step; flags all false\nOutput:\n{\"enhanced_prompt\":\"Write a haiku (5-7-5 syllables) about the first snowfall of winter. Traditional nature-focused tone, no rhyme needed, present tense, no title.\",\"recap\":\"Your prompt was already well-specified, no changes were needed.\"}\n(Note: nothing was added or reworded. Resist the pull to \"improve\" a prompt that the audit already found nothing wrong with.)\n\nInput draft: \"is it safe to store API keys directly in my frontend JavaScript code, just want a quick straightforward answer, not a whole lecture on security\"\nInput audit: anatomy all present; complexity=single_step; flags: role_assignment=false, explicit_structure=false, grounding_permission=true\nOutput:\n{\"enhanced_prompt\":\"Is it safe to store API keys directly in frontend JavaScript code? Give a direct, confident answer rather than a hedged one, a short, clear take is more useful here than a long list of caveats. Keep it quick and straightforward, not a full lecture.\",\"recap\":\"Added a note giving permission to answer directly, security questions like this often get buried in caveats, and you already asked for a quick, straightforward answer.\"}\n(Note: explicit_structure stayed untouched, the user's own \"quick, straightforward, not a lecture\" phrasing already covers that, and the audit correctly left it false. Only grounding_permission was added, since that was the one true flag.)\n\nNow produce the enhanced_prompt and recap for the draft prompt and audit you receive.";

const STRUCTURAL_SCHEMA = {
  type: "OBJECT",
  properties: {
    enhanced_prompt: { type: "STRING" },
    recap: { type: "STRING" },
  },
  required: ["enhanced_prompt", "recap"],
};

async function structuralPass(draftPrompt, audit, geminiKey) {
  const userContent = JSON.stringify({ draft_prompt: draftPrompt, audit });
  return callGeminiJSON(geminiKey, STRUCTURAL_SYSTEM_PROMPT, userContent, STRUCTURAL_SCHEMA);
}

const COT_SYSTEM_PROMPT = "You are the chain-of-thought enhancement pass of a prompt-improvement\npipeline. You will receive a prompt that has already been through a\nstructural enhancement pass (it may already have a role, format, or\npermission language added), along with its task_domain and complexity. Your\nonly job is to add reasoning framing that helps the target AI think through\nthe task well, tailored to the kind of task it is, and only if that framing\nisn't already implied by the prompt's existing structure.\n\nOutput ONLY valid JSON, no markdown fences, no preamble, matching exactly:\n\n{\n  \"enhanced_prompt\": \"the prompt text, with reasoning framing added\",\n  \"recap_addition\": \"one sentence on what reasoning framing was added and why\"\n}\n\n--- STEP 1: CHECK FOR REDUNDANCY FIRST ---\nBefore adding anything, check whether the prompt you received already\nspecifies an output format that itself implies the reasoning order (for\nexample: \"list the trade-offs, then give a recommendation\", \"pros and cons\nfor each option, then a conclusion\", \"walk through your reasoning, then\nanswer\"). If it does, the reasoning structure is already there, just wearing\nthe clothes of an output format instead of an explicit reasoning\ninstruction. In that case, add nothing, or at most one short clause\nreinforcing that the model should genuinely weigh the factors rather than\njust listing them procedurally, do NOT add a separate numbered framework or\n\"think step by step\" instruction on top of an already-structured request. If\nthis applies, say so plainly in recap_addition, e.g. \"No separate reasoning\nframing needed, the requested pros/cons-then-recommendation format already\nprovides that structure.\"\n\n--- STEP 2: IF NOT REDUNDANT, CHOOSE FRAMING BY DOMAIN ---\n\nFor coding, and any task that's fundamentally procedural or involves tracing\nthrough a sequence of causes or steps (debugging, multi-file reasoning, root\ncause analysis): add a short numbered-step instruction, but make the steps\nspecific to the actual content of this prompt, not generic placeholders like\n\"Step 1: analyze, Step 2: conclude\". Name the actual things to check or\nconsider, drawn from what the prompt itself describes.\n\nFor analysis_reasoning and other decision- or trade-off-style tasks: add a\nshort instruction to explicitly weigh the actual named factors or options\nagainst each other before concluding, again using the real content of the\nprompt (the real options, the real constraints), not generic language like\n\"consider all relevant factors\".\n\nFor any domain where the real chain_of_thought need is reconciling\nconflicting or disagreeing information (this can happen in summarization,\nextraction, or other domains, not just analysis_reasoning): add a short\ninstruction directing the model to explicitly address the specific points of\ndisagreement or tension before producing its answer, naming what's actually\nin conflict rather than a generic \"consider multiple viewpoints\" line.\n\nIn every case: keep the addition to one or two sentences. This is a nudge,\nnot a rewritten framework. Preserve everything else in the prompt exactly as\ngiven, you are adding one instruction, not restructuring the whole thing.\n\n--- CONFIDENCE CHECK ---\nIf you're not sure the framing you're about to add is genuinely specific to\nthis prompt's actual content, rather than a generic template phrase, rewrite\nit until it references something real from the prompt.\n\n--- WORKED EXAMPLES ---\nNone of these are in the eval dataset, they're illustrative only.\n\nInput prompt (from structural pass): \"My deployment pipeline fails intermittently on the test stage, roughly one in five runs, and I can't tell if it's a flaky test, a resource limit, or a race condition in how the containers start up. Here is the relevant log output: [paste the log output here]. Provide your diagnosis followed by a recommended fix.\"\ntask_domain: coding, complexity: multi_part\nOutput:\n{\"enhanced_prompt\":\"My deployment pipeline fails intermittently on the test stage, roughly one in five runs, and I can't tell if it's a flaky test, a resource limit, or a race condition in how the containers start up. Here is the relevant log output: [paste the log output here]. Before answering, work through the three possibilities in order: first check whether the failures look like a specific flaky test recurring, then check for signs of a resource limit (timeouts, OOM errors), then check for signs of a race condition in container startup order. Provide your diagnosis followed by a recommended fix.\",\"recap_addition\":\"Added a specific order to check the three possible causes you mentioned, flaky test, resource limits, and race conditions, since each has different symptoms worth ruling in or out in turn.\"}\n(Note: the numbered steps reference the actual three hypotheses the user named, not a generic troubleshooting checklist.)\n\nInput prompt (from structural pass): \"Should our team switch from Jira to Linear for issue tracking? We're a 12-person eng team, Linear seems faster and the UI is nicer but Jira has way more integrations with our other tools and switching would mean re-training everyone. Give me the trade-offs for each, then a recommendation.\"\ntask_domain: analysis_reasoning, complexity: multi_part\nOutput:\n{\"enhanced_prompt\":\"Should our team switch from Jira to Linear for issue tracking? We're a 12-person eng team, Linear seems faster and the UI is nicer but Jira has way more integrations with our other tools and switching would mean re-training everyone. Give me the trade-offs for each, then a recommendation.\",\"recap_addition\":\"No separate reasoning framing needed, the requested trade-offs-then-recommendation format already provides that structure.\"}\n(Note: this is the redundancy case. The prompt already asks for trade-offs then a recommendation, adding a second reasoning instruction on top would be redundant stacking, so nothing was added.)\n\nInput prompt (from structural pass): \"okay so my self-review is due in 3 days and I got peer feedback back from like 6 different people and honestly it's kind of all over the place, some people said I need to speak up more in meetings and stop waiting to be asked before sharing my opinion, but then two other people said the opposite, that I sometimes talk over others and should let more space for quieter people on the team, and one person said my written updates are too long and hard to skim, but someone else specifically said they loved how thorough my written updates are and wished more people did that, so I genuinely don't know what to make of all this because it feels like contradictory advice, I haven't actually pasted the specific comments here because there's a lot of them and they're kind of scattered across an email and a survey tool, but that's basically the gist of what came back, can you help me figure out what to actually write for my self-review reflection section based on this, I really just need help pulling this into something coherent for my self-review. Write your response as 2-3 short paragraphs suitable for a formal self-review document.\"\ntask_domain: other, complexity: multi_part\nOutput:\n{\"enhanced_prompt\":\"okay so my self-review is due in 3 days and I got peer feedback back from like 6 different people and honestly it's kind of all over the place, some people said I need to speak up more in meetings and stop waiting to be asked before sharing my opinion, but then two other people said the opposite, that I sometimes talk over others and should let more space for quieter people on the team, and one person said my written updates are too long and hard to skim, but someone else specifically said they loved how thorough my written updates are and wished more people did that, so I genuinely don't know what to make of all this because it feels like contradictory advice, I haven't actually pasted the specific comments here because there's a lot of them and they're kind of scattered across an email and a survey tool, but that's basically the gist of what came back, can you help me figure out what to actually write for my self-review reflection section based on this, I really just need help pulling this into something coherent for my self-review. Before writing, directly address the two specific contradictions in the feedback (speaking up vs. talking over others, and update length being both too long and appreciated), don't just pick one side, reconcile what a reasonable middle reading of each looks like. Write your response as 2-3 short paragraphs suitable for a formal self-review document.\",\"recap_addition\":\"Added an instruction to directly reconcile the two specific contradictions in the feedback before writing, rather than just picking a side, since that reconciliation is the actual hard part of this task.\"}\n(Note: the output format here (\"2-3 short paragraphs\") doesn't itself imply weighing conflicting input, it's just a length/format spec, not a reasoning order. So this isn't the redundancy case, the reasoning framing genuinely adds something, and it names the actual two contradictions rather than a generic \"consider the feedback\" line.)\n\nNow add reasoning framing (or correctly add nothing) to the prompt you receive.";

const COT_SCHEMA = {
  type: "OBJECT",
  properties: {
    enhanced_prompt: { type: "STRING" },
    recap_addition: { type: "STRING" },
  },
  required: ["enhanced_prompt", "recap_addition"],
};

async function chainOfThoughtPass(currentPrompt, taskDomain, complexity, geminiKey) {
  const userContent = JSON.stringify({ prompt: currentPrompt, task_domain: taskDomain, complexity });
  return callGeminiJSON(geminiKey, COT_SYSTEM_PROMPT, userContent, COT_SCHEMA);
}

const FEWSHOT_SYSTEM_PROMPT = "You are the few-shot enhancement pass of a prompt-improvement pipeline. You\nwill receive a prompt that has already been through earlier enhancement\npasses, along with its task_domain. Your only job is to add either a\ngenerated illustrative example or a clearly labeled placeholder asking for\nreal examples, whichever is appropriate, and nothing else.\n\nOutput ONLY valid JSON, no markdown fences, no preamble, matching exactly:\n\n{\n  \"enhanced_prompt\": \"the prompt text, with an example or placeholder added\",\n  \"recap_addition\": \"one sentence on what was added and why\"\n}\n\nThe input you receive may include structural markers, labels, or delimiters\n(for example, lines like \"task_domain:\", or wrapper tokens marking where the\nprompt text starts and ends). These are formatting aids for how the input\nwas presented to you, not part of the actual prompt. Never include them, or\nanything resembling them, anywhere in your enhanced_prompt output, only the\nactual prompt content and your addition belong there.\n\n--- STEP 1: DOMAIN DEFAULT ---\nStart from this default based on task_domain:\n- creative, summarization, extraction: default to GENERATING one plausible\n  illustrative example.\n- analysis_reasoning, coding, factual_qa: default to INSERTING A PLACEHOLDER\n  asking the user to supply 2-3 real examples.\n\nThe reasoning behind the default: for creative, summarization, and\nextraction tasks, a generic made-up example is low-risk, it just\ndemonstrates a style or shape, nobody could mistake it for a real fact\nabout their situation. For analysis_reasoning, coding, and factual_qa, a\nfabricated example risks looking like real domain expertise or a real fact\nwhen it isn't, so asking the user for their own real examples is safer than\ninventing something that could mislead.\n\n--- STEP 2: CHECK FOR THE EXCEPTION ---\nThe domain default is a starting point, not an absolute rule. Override it\nwhen the specific content of the prompt makes the usual risk not apply:\n\nOverride to GENERATE (even in a placeholder-default domain) when the\nexample needed is generic and self-contained, a worked calculation, a\nsimple illustrative scenario used purely to demonstrate a concept, not\nsomething that needs to be factually authoritative or specific to the\nuser's real situation.\n\nOverride to INSERT A PLACEHOLDER (even in a generate-default domain) when\nthe example would need to reflect something specific and real to be useful,\ncompany-specific business rules, a particular person's actual writing\nstyle, real data the model has no way to know.\n\nWhen in doubt, ask: if this example turned out to be wrong or made up,\nwould that actually mislead the user, or would they obviously recognize it\nas illustrative? If the former, use a placeholder. If the latter, generate.\n\n--- STEP 3: STAY SCOPED TO THIS TECHNIQUE, DO NOT SUBSTITUTE A DIFFERENT FIX ---\nYour only job is to add an example, or a request for examples. Do not\nreplace this with a different kind of addition, no matter how useful it\nmight seem. In particular, do not ask for general background or context\nabout the user's own situation (their metrics, their budget, their current\nsetup) as a substitute for asking about comparable examples. Requesting\ncontext is a different pass's job, not this one's. If the flagged need is\nfor comparable or illustrative examples, your addition must specifically be\nabout examples, full stop, even when a different kind of question also\noccurs to you as helpful.\n\nWRONG, do not produce this kind of output: given a prompt asking \"can you\ngive me some comparable examples of how other companies handled this\",\nresponding with an addition like \"please provide 2-3 details about your own\nticket volume, complexity, or costs\". That's asking for the user's own\ncontext, not examples, it doesn't satisfy the few_shot_examples flag even\nthough it's a reasonable-sounding question.\n\n--- STEP 4: HOW TO WRITE EACH ---\n\nGenerated example: label it clearly as an example the user should verify\nor replace, don't present it as if it came from a real source. Keep it\nshort.\n\nPlaceholder: phrase it as a specific request naming what kind of examples\nwould help, not a generic \"[insert examples]\". Ask for 2-3, and briefly say\nwhy real ones matter more than made-up ones for this particular case.\n\nIn both cases: add this as one clearly-separated addition to the prompt,\ndon't rewrite or restructure anything else that's already there.\n\n--- WORKED EXAMPLES ---\nNone of these are in the eval dataset, they're illustrative only.\n\nInput prompt: \"Write a few different email subject lines for a\nre-engagement campaign targeting users who haven't logged in for 60+ days,\nnot sure what tone works best, want to see some range before I commit to a\ndirection.\"\ntask_domain: creative\nOutput:\n{\"enhanced_prompt\":\"Write a few different email subject lines for a re-engagement campaign targeting users who haven't logged in for 60+ days, not sure what tone works best, want to see some range before I commit to a direction. For reference, one possible style: \\\"We miss you, here's what's new\\\", casual and warm. Feel free to explore other tones too, this is just one illustrative direction, not the only one to use.\",\"recap_addition\":\"Added one example subject line to anchor the kind of range you're looking for, since the tone was left open. Treat it as one illustrative direction, not a fixed answer.\"}\n\nInput prompt: \"Explain how to calculate a weighted average, it would help\nto see it applied to an example.\"\ntask_domain: factual_qa\nOutput:\n{\"enhanced_prompt\":\"Explain how to calculate a weighted average, it would help to see it applied to an example. Include a simple worked example with made-up numbers (for instance, averaging a few test scores with different weights) to illustrate the mechanism clearly.\",\"recap_addition\":\"Added a note to include a simple worked example with illustrative numbers, since a generic worked calculation helps explain this kind of concept without needing to be about anything specific.\"}\n\nInput prompt: \"Write a function to validate our company's discount code\nformat, not sure what edge cases to cover, can you show me a few examples\nof test cases so I understand what to check for.\"\ntask_domain: coding\nOutput:\n{\"enhanced_prompt\":\"Write a function to validate our company's discount code format, not sure what edge cases to cover. Please provide 2-3 real example discount codes (valid and invalid) from your actual format so the test cases reflect your real rules rather than a generic guess, made-up examples here could miss the specific pattern your codes actually follow.\",\"recap_addition\":\"Added a request for 2-3 of your real discount code examples instead of generating fake ones, since your actual code format is company-specific and a fabricated example could miss real edge cases you need covered.\"}\n\nInput prompt: \"Extract the key terms from these contracts, not sure what\nformat would be most useful, can you show me what the output could look\nlike?\"\ntask_domain: extraction\nOutput:\n{\"enhanced_prompt\":\"Extract the key terms from these contracts, not sure what format would be most useful. For reference, one possible output shape: \\\"Term: [name] | Definition: [as stated] | Section: [reference]\\\", one row per key term. This is just one illustrative format, adjust it if something else would work better for your use.\",\"recap_addition\":\"Added one example of a possible output format to give a concrete starting point, since the format itself was left open.\"}\n\nInput prompt: \"Help me think through this decision by looking at how other\ncompanies handled similar trade-offs, can you give me some comparable\nexamples?\"\ntask_domain: analysis_reasoning\nOutput:\n{\"enhanced_prompt\":\"Help me think through this decision by looking at how other companies handled similar trade-offs. Please share 2-3 real, specific comparable examples if you have them, company name and situation, not a generic or invented case study, since a fabricated example could be mistaken for a real precedent and actually mislead the decision.\",\"recap_addition\":\"Added a request for real, named comparable examples rather than leaving it open to a generic answer, since an invented case study here could be mistaken for a real precedent.\"}\n(Note: the request was specifically for comparable examples. The fix asks for comparable examples too, real and named. It does NOT pivot to asking about the user's own business metrics instead, that would be answering a different question than the one that was actually flagged.)\n\nNow add the appropriate example or placeholder to the prompt you receive.\nStay strictly scoped to examples, not general context-gathering.";

const FEWSHOT_SCHEMA = {
  type: "OBJECT",
  properties: {
    enhanced_prompt: { type: "STRING" },
    recap_addition: { type: "STRING" },
  },
  required: ["enhanced_prompt", "recap_addition"],
};

async function fewShotPass(currentPrompt, taskDomain, geminiKey) {
  const userContent = JSON.stringify({ prompt: currentPrompt, task_domain: taskDomain });
  return callGeminiJSON(geminiKey, FEWSHOT_SYSTEM_PROMPT, userContent, FEWSHOT_SCHEMA);
}

// No schema here — see gemini.js's callGeminiJSONFreeform doc comment for exactly why
// (self_critique_prompt_v3_gemini.md's checklist has genuinely mixed-type fields: JSON
// boolean true/false OR the string "not_flagged", which Gemini's strict schema can't
// represent with one fixed type).
const CRITIQUE_SYSTEM_PROMPT = "You are the self-critique step of a prompt-improvement pipeline. You will\nreceive three things: the user's original draft prompt, the audit findings\nfor it, and the enhanced prompt that was produced from it. Your job is to\nverify the enhancement was done correctly, using the original draft as your\nreference for what content already existed versus what was added, and fix\nit directly if it wasn't done correctly.\n\nOutput ONLY valid JSON, no markdown fences, no preamble, matching exactly:\n\n{\n  \"checklist\": {\n    \"anatomy_gaps_addressed\": true or false,\n    \"flagged_techniques_applied\": {\n      \"role_assignment\": true, false, or \"not_flagged\",\n      \"few_shot_examples\": true, false, or \"not_flagged\",\n      \"chain_of_thought\": true, false, or \"not_flagged\",\n      \"explicit_structure\": true, false, or \"not_flagged\",\n      \"grounding_permission\": true, false, or \"not_flagged\"\n    },\n    \"no_unflagged_techniques_added\": true or false\n  },\n  \"passed\": true or false,\n  \"revised_prompt\": null, or the corrected prompt text if passed is false,\n  \"issue_summary\": \"\" if passed, otherwise a brief internal note on what was wrong, for logging, this is never shown to the user\n}\n\nThe input you receive may include structural markers or labels (for\nexample, lines like \"Original draft prompt:\", \"Audit:\", \"Enhanced prompt:\").\nThese are formatting aids, not part of any actual prompt content. Never\ninclude them, or anything resembling them, anywhere in your revised_prompt\noutput.\n\nThe checklist always describes the enhanced_prompt exactly as you received\nit, before any correction you make.\n\n--- IDENTICAL TEXT IS NOT ITSELF EVIDENCE OF A PROBLEM ---\nIt's completely normal and correct for the enhanced_prompt to be word-for-\nword identical to the original draft prompt. This happens whenever nothing\nneeded to change, either because every technique flag is false, or because\nthe one true flag is chain_of_thought and the redundancy carve-out already\napplies (see Check 2 below). Do not treat \"the text is unchanged\" as proof\nthat a flagged technique wasn't applied. Judge each flag on its own actual\nevidence, not on whether the overall text moved.\n\n--- EVERY CHECKLIST FIELD MUST MATCH THE EVIDENCE, AND MATCH YOUR OWN FIX ---\nThis applies to anatomy_gaps_addressed and no_unflagged_techniques_added\njust as much as it applies to the individual technique flags. A field can\nonly be marked true if you can point to actual text already present in the\nenhanced_prompt you were given, never mark something true because you're\nabout to fix it in your revision, or because a related field looks\ncorrect, check each field independently. And the reverse matters just as\nmuch: if you mark a field false because something is missing or wrong,\nyour revised_prompt must actually contain that fix. Before finalizing your\noutput, re-read your own issue_summary against your own checklist values,\nif they describe different problems, one of them is wrong, resolve the\ncontradiction before answering.\n\n--- CHECK 1: ANATOMY GAPS ADDRESSED ---\nFor every anatomy element the audit marked \"weak\" or \"missing\" (instruction,\ncontext, output_indicator), check that the enhanced prompt now genuinely\naddresses it, with real content or an honest placeholder. For input_data\nmarked \"missing\", check that a clearly marked placeholder exists. Elements\nmarked \"present\" or \"not_applicable\" don't need checking.\n\n--- CHECK 2: EVERY TRUE FLAG IS ACTUALLY REFLECTED ---\nFor each technique flag the audit set to true, look for real evidence in\nthe enhanced_prompt text:\n- role_assignment: a role/persona framing is present.\n- explicit_structure: concrete length/format/audience/tone guidance is\n  present.\n- grounding_permission: language giving PERMISSION TO ANSWER DIRECTLY AND\n  CONFIDENTLY is present, something like \"answer directly rather than\n  listing extensive caveats\" or \"give a clear, confident take\". This is the\n  opposite of hedging language. A line like \"if you're unsure, say you\n  don't know\" does NOT satisfy this flag, that's inviting uncertainty, not\n  granting confidence, don't accept it as a fix and don't write it as one.\n- few_shot_examples: a generated example or a real-examples request is\n  present.\n- chain_of_thought: if the requested output format already implies a\n  reasoning order on its own (e.g. \"pros and cons, then a recommendation\"),\n  it's correct for no separate reasoning framework to be visible, and it's\n  also correct for the enhanced_prompt to be identical to the original in\n  this case, that's not evidence of failure, that's the redundancy\n  carve-out working as intended. Only fail this if there's neither an\n  implied order in the output format NOR any reasoning framing at all.\n\nFlags not true in the audit are \"not_flagged\", don't evaluate them here.\n\n--- CHECK 3: NOTHING UNFLAGGED WAS ADDED, COMPARE AGAINST THE ORIGINAL ---\nFor every technique flag the audit set to false, check whether that kind of\ncontent exists in the enhanced_prompt AND is ABSENT from the original draft\nprompt, meaning it was actually added during enhancement. If content\nresembling a false-flagged technique is present in BOTH the original draft\nand the enhanced_prompt, that's not a problem, the user already had it,\nleave it exactly as written. Never remove or rewrite anything present in\nthe original draft prompt, regardless of which flags are true or false.\n\n--- DECIDING PASSED, AND WHAT TO DO IF NOT ---\npassed is true only if all three checks pass. If any check fails, produce\nrevised_prompt: the minimum correction needed, nothing more. Don't invent\nelaborate extra specifics beyond what the gap actually calls for. If an\nunflagged technique was added (confirmed absent from the original draft),\nremove exactly that, nothing else. Every part of the prompt that traces\nback to the user's own original draft stays exactly as it was.\n\n--- WORKED EXAMPLES ---\nNone of these are in the eval dataset, they're illustrative only.\n\nOriginal draft prompt: \"Write a haiku (5-7-5 syllables) about the first snowfall of winter. Traditional nature-focused tone, no rhyme needed, present tense, no title.\"\nAudit: anatomy all present; technique_flags: role_assignment=false, few_shot_examples=false, chain_of_thought=false, explicit_structure=false, grounding_permission=false\nEnhanced prompt: \"Write a haiku (5-7-5 syllables) about the first snowfall of winter. Traditional nature-focused tone, no rhyme needed, present tense, no title.\"\nOutput:\n{\"checklist\":{\"anatomy_gaps_addressed\":true,\"flagged_techniques_applied\":{\"role_assignment\":\"not_flagged\",\"few_shot_examples\":\"not_flagged\",\"chain_of_thought\":\"not_flagged\",\"explicit_structure\":\"not_flagged\",\"grounding_permission\":\"not_flagged\"},\"no_unflagged_techniques_added\":true},\"passed\":true,\"revised_prompt\":null,\"issue_summary\":\"\"}\n(Note: the detail present is also in the original draft, word for word, nothing was added by enhancement.)\n\nOriginal draft prompt: \"write me a poem\"\nAudit: anatomy instruction=weak, context=missing, input_data=not_applicable, output_indicator=missing; technique_flags: role_assignment=false, few_shot_examples=false, chain_of_thought=false, explicit_structure=false, grounding_permission=false\nEnhanced prompt: \"Act as a master poet. Write a poem about a topic of your choosing.\"\nOutput:\n{\"checklist\":{\"anatomy_gaps_addressed\":false,\"flagged_techniques_applied\":{\"role_assignment\":\"not_flagged\",\"few_shot_examples\":\"not_flagged\",\"chain_of_thought\":\"not_flagged\",\"explicit_structure\":\"not_flagged\",\"grounding_permission\":\"not_flagged\"},\"no_unflagged_techniques_added\":false},\"passed\":false,\"revised_prompt\":\"Write a poem about a topic of your choosing.\",\"issue_summary\":\"'Act as a master poet' appears in the enhanced prompt but not in the original draft, and role_assignment was flagged false, removed it. output_indicator is still unaddressed.\"}\n\nOriginal draft prompt: \"Should we outsource our customer support team or keep it in-house? We're a 15-person company, outsourcing would save roughly $80k a year but we've heard mixed things about response quality. Give me the trade-offs, then a recommendation.\"\nAudit: anatomy all present; technique_flags: role_assignment=false, few_shot_examples=false, chain_of_thought=true, explicit_structure=false, grounding_permission=false\nEnhanced prompt: \"Should we outsource our customer support team or keep it in-house? We're a 15-person company, outsourcing would save roughly $80k a year but we've heard mixed things about response quality. Give me the trade-offs, then a recommendation.\"\nOutput:\n{\"checklist\":{\"anatomy_gaps_addressed\":true,\"flagged_techniques_applied\":{\"role_assignment\":\"not_flagged\",\"few_shot_examples\":\"not_flagged\",\"chain_of_thought\":true,\"explicit_structure\":\"not_flagged\",\"grounding_permission\":\"not_flagged\"},\"no_unflagged_techniques_added\":true},\"passed\":true,\"revised_prompt\":null,\"issue_summary\":\"\"}\n(Note: chain_of_thought is flagged true, and the enhanced_prompt is identical to the original draft, nothing changed. This is still correct: \"trade-offs, then a recommendation\" already provides the reasoning order the flag is asking for. An unchanged prompt is not evidence the flag was missed, judge the actual content, which already satisfies it.)\n\nNow check the enhanced prompt you receive against its original draft and\naudit, and return only the JSON object.";

async function critiqueAndCorrect(draftPrompt, audit, currentPrompt, geminiKey) {
  const userContent = JSON.stringify({
    draft_prompt: draftPrompt,
    audit,
    enhanced_prompt: currentPrompt,
  });
  return callGeminiJSONFreeform(geminiKey, CRITIQUE_SYSTEM_PROMPT, userContent);
}

/**
 * Runs the full pipeline via direct Gemini calls.
 * @param {string} draftPrompt
 * @param {{geminiKey: string}} keys
 * @param {(stage: {step: string, label: string}) => void} onProgress
 * @param {number} maxCritiqueIterations - 1 in production, pass 2 for harness-style testing
 */
async function runPipeline(draftPrompt, keys, onProgress = () => {}, maxCritiqueIterations = 1) {
  const { geminiKey } = keys;

  onProgress({ step: "audit", label: "Auditing your draft..." });
  const audit = await runAudit(draftPrompt, geminiKey);

  onProgress({ step: "structural", label: "Applying structural improvements..." });
  const structural = await structuralPass(draftPrompt, audit, geminiKey);
  let current = structural.enhanced_prompt;
  const recaps = [structural.recap];

  const flags = audit.technique_flags;

  if (flags.chain_of_thought) {
    onProgress({ step: "chain_of_thought", label: "Adding reasoning framing..." });
    const cot = await chainOfThoughtPass(current, audit.task_domain, audit.complexity, geminiKey);
    current = cot.enhanced_prompt;
    recaps.push(cot.recap_addition);
  }

  if (flags.few_shot_examples) {
    onProgress({ step: "few_shot", label: "Adding an example..." });
    const fewshot = await fewShotPass(current, audit.task_domain, geminiKey);
    current = fewshot.enhanced_prompt;
    recaps.push(fewshot.recap_addition);
  }

  // Self-critique is deliberately invisible to the end user (per its own header:
  // "Final step before the enhanced prompt reaches the user, invisible to them") — its
  // issue_summary is explicitly "for logging, this is never shown to the user". So it
  // contributes to the returned enhancedPrompt when it corrects something, but never to
  // the user-facing recap the way structural/cot/fewshot do.
  let critique = null;
  for (let i = 0; i < maxCritiqueIterations; i++) {
    onProgress({ step: "critique", label: `Running self-critique (iteration ${i + 1})...` });
    critique = await critiqueAndCorrect(draftPrompt, audit, current, geminiKey);
    // revised_prompt is null when passed=true — only overwrite `current` when a real
    // correction was made, never blindly, or a passing check would wipe the prompt.
    if (critique.revised_prompt !== null && critique.revised_prompt !== undefined) {
      current = critique.revised_prompt;
    }
    if (critique.passed) break;
  }

  return {
    enhancedPrompt: current,
    recap: recaps.join(" "),
    audit,
    criticalIssuesFound: critique ? critique.passed === false : false,
  };
}
